import{_ as e,o as a,c as d,ak as o}from"./chunks/framework.DKi5cyCJ.js";const I=JSON.parse('{"title":"嵌入式网络","description":"RMII、ARP、UDP 数据报、TCP 三次握手与四次挥手、LwIP 窗口","frontmatter":{"title":"嵌入式网络","description":"RMII、ARP、UDP 数据报、TCP 三次握手与四次挥手、LwIP 窗口","date":"2026-10-20T00:00:00.000Z"},"headers":[],"relativePath":"pages/blog/2026-10-20-嵌入式网络TCP与UDP.md","filePath":"pages/blog/2026-10-20-嵌入式网络TCP与UDP.md"}'),l={name:"pages/blog/2026-10-20-嵌入式网络TCP与UDP.md"};function p(r,t,c,P,i,s){return a(),d("div",null,[...t[0]||(t[0]=[o('<h1 id="网络-udp、tcp-握手与-lwip" tabindex="-1">网络：UDP、TCP 握手与 LwIP <a class="header-anchor" href="#网络-udp、tcp-握手与-lwip" aria-label="Permalink to &quot;网络：UDP、TCP 握手与 LwIP&quot;">​</a></h1><blockquote><p>系列目录：<a href="/pages/blog/2026-10-20-嵌入式驱动面试手册.html">嵌入式驱动面试手册</a></p></blockquote><p>MCU 侧常见结构是 MAC、外接 PHY、带变压器的 RJ45。排查按层走：PHY ID、Link、描述符、ARP、ICMP、TCP。百兆 RMII 的参考时钟是 50 MHz，只能有一个时钟源。PHY ID 在寄存器 2 和 3，读出来全 0 或全 1 时先查地址、复位和 MDIO。</p><p>同一子网发 IP 之前要 ARP。跨网段 ARP 的是网关。判断方法是本机 IP 和目标 IP 分别与掩码相与，结果相同才算同一子网。</p><h2 id="udp" tabindex="-1">UDP <a class="header-anchor" href="#udp" aria-label="Permalink to &quot;UDP&quot;">​</a></h2><p>无连接数据报。首部 8 字节：源端口、目的端口、长度、校验和。一次发送对应一个报文，接收端一次读回这个报文，边界还在。不编号、不重传。以太网 MTU 1500 时，UDP 载荷上限 1472 字节。</p><p>UDP 本身没有握手。DHCP 的 Discover、Offer、Request、Ack 是跑在 UDP 上的四步应用流程。</p><h2 id="tcp" tabindex="-1">TCP <a class="header-anchor" href="#tcp" aria-label="Permalink to &quot;TCP&quot;">​</a></h2><p>字节流。两次 write 可能被合并成一次 read，仪器协议要自己加长度或定界符。</p><div class="blog-flow"><div class="blog-flow-col"><div class="blog-flow-node">建立：SYN → SYN+ACK → ACK</div><div class="blog-flow-down">SYN 消耗一个序号，确认号是 x+1</div><div class="blog-flow-node accent">关闭：FIN → ACK → FIN → ACK</div><div class="blog-flow-down">TIME_WAIT 只留在主动关闭的一方，长度 2MSL</div></div></div><table tabindex="0"><thead><tr><th>步骤</th><th>主动打开 / 主动关闭</th><th>被动一方</th></tr></thead><tbody><tr><td>发出 SYN</td><td>SYN_SENT</td><td>LISTEN → SYN_RCVD</td></tr><tr><td>握手完成</td><td>ESTABLISHED</td><td>ESTABLISHED</td></tr><tr><td>发出 FIN</td><td>FIN_WAIT_1 → FIN_WAIT_2</td><td>CLOSE_WAIT</td></tr><tr><td>最后的 FIN/ACK</td><td>TIME_WAIT</td><td>LAST_ACK → CLOSED</td></tr></tbody></table><p>服务端在 SYN_RCVD 就要占用一个连接块。RST 直接拆连接，不进 TIME_WAIT。可靠靠序号、累计确认和超时重传；连续 3 个重复 ACK 会快重传。接收窗口是流量控制，拥塞窗口是另一套限制，实际发送量取较小值。</p><p>LwIP 收到数据后必须调用 <code>tcp_recved</code>，否则窗口保持 0，连接看起来像卡死。<code>tcp_write</code> 之后要 <code>tcp_output</code>。回调里 <code>p == NULL</code> 表示对端已经 FIN。交互命令可以关 Nagle，避免小包被攒住。</p><p>ping 通只说明 ICMP 往返正常，不能说明 TCP 端口开着。M7 上 DMA 缓冲还要处理 Cache，见 <a href="/pages/blog/2026-10-20-Cache与DMA一致性.html">Cache 与 DMA</a>。</p><p><a href="/pages/blog/2026-10-20-嵌入式驱动面试手册.html">返回目录</a></p>',15)])])}const T=e(l,[["render",p]]);export{I as __pageData,T as default};
